/* The metadata of an entry, next to the session directory it holds. */
#define META_FILE "meta.json"

/* The trash inside the program's data directory; NULL when there is none. */
char *trash_path(const struct move_ctx *ctx)
{
	return ctx->data_dir != NULL ? xjoin(ctx->data_dir, "trash") : NULL;
}

/*
 * "20261027T224714Z-Users-m-repo": the time of removal (UTC) and the
 * session directory, so the names sort by time. n > 1 tells apart two
 * removals of one directory in the same second.
 */
char *trash_entry_name(time_t when, const char *dir, unsigned n)
{
	struct tm tm;
	char stamp[32], num[16], *name;

	if (gmtime_r(&when, &tm) == NULL ||
	    strftime(stamp, sizeof stamp, "%Y%m%dT%H%M%SZ", &tm) == 0)
		strcpy(stamp, "19700101T000000Z");
	num[0] = '\0';
	if (n > 1)
		snprintf(num, sizeof num, "-%u", n);
	name = xmalloc(strlen(stamp) + strlen(dir) + strlen(num) + 2);
	sprintf(name, "%s%s%s%s", stamp, dir[0] == '-' ? "" : "-", dir, num);
	return name;
}

static char *add(char *s, const char *t)
{
	size_t n, m;

	n = strlen(s);
	m = strlen(t);
	s = xrealloc(s, n + m + 1);
	memcpy(s + n, t, m + 1);
	return s;
}

static char *add_field(char *s, const char *name, const char *value)
{
	char *enc;

	s = add(s, s[1] == '\0' ? "\n  \"" : ",\n  \"");
	s = add(s, name);
	s = add(s, "\": ");
	if (value == NULL)
		return add(s, "null");
	enc = json_encode_string(value);
	s = add(s, "\"");
	s = add(s, enc);
	s = add(s, "\"");
	free(enc);
	return s;
}

/* The projects entry goes in as the raw JSON it was, byte for byte. */
static char *meta_text(const struct trash_entry *e)
{
	char *s, *when;

	when = format_iso(e->removed);
	s = xstrdup("{");
	s = add_field(s, "dir", e->dir);
	s = add_field(s, "path", e->origin);
	s = add_field(s, "project", e->project);
	s = add_field(s, "configDir", e->config_dir);
	s = add_field(s, "configFile", e->config_file);
	s = add_field(s, "removed", when);
	if (e->projects_key != NULL) {
		s = add_field(s, "projectsKey", e->projects_key);
		s = add(s, ",\n  \"projectsEntry\": ");
		s = add(s, e->projects_value);
	}
	free(when);
	return add(s, "\n}\n");
}

static int meta_write(const struct trash_entry *e)
{
	struct atomic_file *af;
	char *file, *text;
	int status, saved;

	file = xjoin(e->path, META_FILE);
	af = atomic_open(file, 0600);
	free(file);
	if (af == NULL)
		return -1;
	text = meta_text(e);
	status = atomic_write(af, text, strlen(text));
	free(text);
	if (status != 0) {
		saved = errno;
		atomic_abort(af);
		errno = saved;
		return -1;
	}
	return atomic_commit(af, NULL);
}

struct raw_find {
	size_t start, end;
	int found;
};

static void find_entry(const struct json_token *tok, void *ctx)
{
	struct raw_find *f = ctx;

	if (!tok->is_key && tok->depth == 1 && tok->path[0].key != NULL &&
	    strcmp(tok->path[0].key, "projectsEntry") == 0) {
		f->start = tok->start;
		f->end = tok->end;
		f->found = 1;
	}
}

/* Fills e from the entry's metadata; fields stay NULL when unreadable. */
static void meta_read(struct trash_entry *e)
{
	struct raw_find f;
	char *file, *data, *when;
	size_t len;

	file = xjoin(e->path, META_FILE);
	if (file_read(file, &data, &len) != 0) {
		free(file);
		return;
	}
	free(file);
	memset(&f, 0, sizeof f);
	if (json_scan(data, len, find_entry, &f) != 0) {
		free(data);
		return;
	}
	e->dir = json_top_string(data, "dir");
	e->origin = json_top_string(data, "path");
	e->project = json_top_string(data, "project");
	e->config_dir = json_top_string(data, "configDir");
	e->config_file = json_top_string(data, "configFile");
	e->projects_key = json_top_string(data, "projectsKey");
	when = json_top_string(data, "removed");
	if (when != NULL)
		parse_iso(when, &e->removed);
	free(when);
	if (e->projects_key != NULL && f.found) {
		e->projects_value = xmalloc(f.end - f.start + 1);
		memcpy(e->projects_value, data + f.start, f.end - f.start);
		e->projects_value[f.end - f.start] = '\0';
	} else {
		free(e->projects_key);
		e->projects_key = NULL;
	}
	/* Without these an entry cannot go back. */
	if (e->dir == NULL || e->origin == NULL || strchr(e->dir, '/') != NULL) {
		free(e->dir);
		free(e->origin);
		e->dir = e->origin = NULL;
	}
	free(data);
}

/*
 * Reads the entry name of the trash. Names come from the user, so only a
 * plain directory name counts: no "/", no dot first (temporary files). -1
 * with errno ENOENT when there is no such entry.
 */
int trash_read(const char *trash, const char *name, struct trash_entry *e)
{
	struct stat st;
	time_t newest = 0;
	int any = 0, saved;

	memset(e, 0, sizeof *e);
	errno = ENOENT;
	if (name[0] == '\0' || name[0] == '.' || strchr(name, '/') != NULL) {
		errno = ENOENT;
		return -1;
	}
	e->name = xstrdup(name);
	e->path = xjoin(trash, name);
	if (lstat(e->path, &st) != 0 || !S_ISDIR(st.st_mode)) {
		saved = errno;
		trash_entry_free(e);
		errno = saved;
		return -1;
	}
	meta_read(e);
	inventory_walk(e->path, &e->size, &newest, &any);
	if (e->removed == 0)
		e->removed = st.st_mtime;
	return 0;
}

static int compare_entries(const void *a, const void *b)
{
	const struct trash_entry *x = a, *y = b;

	return strcmp(x->name, y->name);
}

/* All entries, oldest first; a missing trash is empty. -1 with errno. */
int trash_list(const char *trash, struct trash_entry **entries,
    size_t *count)
{
	struct dirent *d;
	size_t cap = 0;
	DIR *dir;

	*entries = NULL;
	*count = 0;
	dir = opendir(trash);
	if (dir == NULL)
		return errno == ENOENT ? 0 : -1;
	while ((d = readdir(dir)) != NULL) {
		if (*count == cap) {
			cap = cap ? cap * 2 : 16;
			*entries = xrealloc(*entries, cap * sizeof **entries);
		}
		if (trash_read(trash, d->d_name, &(*entries)[*count]) == 0)
			(*count)++;
	}
	closedir(dir);
	if (*count > 0)
		qsort(*entries, *count, sizeof **entries, compare_entries);
	return 0;
}

void trash_entry_free(struct trash_entry *e)
{
	free(e->name);
	free(e->path);
	free(e->dir);
	free(e->origin);
	free(e->project);
	free(e->config_dir);
	free(e->config_file);
	free(e->projects_key);
	free(e->projects_value);
	memset(e, 0, sizeof *e);
}

void trash_list_free(struct trash_entry *entries, size_t count)
{
	size_t i;

	for (i = 0; i < count; i++)
		trash_entry_free(&entries[i]);
	free(entries);
}

/*
 * The projects entry of key in file: *value is its raw JSON (NULL when
 * there is none), *out the file without it. A missing file has none. -1
 * when the file cannot be read or is not valid JSON, noted.
 */
static int take_entry(struct move_ctx *ctx, const char *file, const char *key,
    char **value, char **out, size_t *out_len)
{
	char *data;
	size_t len;
	int status;

	*value = *out = NULL;
	*out_len = 0;
	if (file_read(file, &data, &len) != 0) {
		if (errno == ENOENT)
			return 0;
		move_note(ctx, NOTE_ERROR, "error.read", file, NULL, errno);
		return -1;
	}
	status = config_take_project(data, len, key, value, out, out_len);
	free(data);
	if (status == REWRITE_INVALID) {
		move_note(ctx, NOTE_WARNING, "warn.invalid", file, NULL, 0);
		return -1;
	}
	return 0;
}

/* A new, empty entry for the session directory dir; NULL when noted. */
static char *new_entry(struct move_ctx *ctx, const char *trash,
    const char *dir, time_t now)
{
	char *name, *path;
	unsigned n;

	if (dir_make(trash, 0700) != 0) {
		move_note(ctx, NOTE_ERROR, "error.trash", trash, NULL, errno);
		return NULL;
	}
	for (n = 1;; n++) {
		name = trash_entry_name(now, dir, n);
		path = xjoin(trash, name);
		free(name);
		if (mkdir(path, 0700) == 0)
			return path;
		if (errno != EEXIST) {
			move_note(ctx, NOTE_ERROR, "error.trash", path, NULL,
			    errno);
			free(path);
			return NULL;
		}
		free(path);
	}
}

/* Takes an entry with nothing in it but its metadata back out of the trash. */
static void drop_entry(const char *entry)
{
	char *meta;

	meta = xjoin(entry, META_FILE);
	unlink(meta);
	free(meta);
	rmdir(entry);
}

/*
 * Moves a session directory to the trash (4.6). Its projects entry comes
 * along only when the project path is gone (orphaned), never when it
 * exists or cannot be checked. The steps: metadata with the projects
 * entry, then the directory (confirmed: there, and gone from where it
 * was), then .claude.json. A failed step undoes the earlier ones; at
 * worst a copy stays in the trash and nothing is lost.
 */
void trash_remove(struct move_ctx *ctx, const struct session_dir_info *d)
{
	struct trash_entry e;
	struct stat st;
	char *trash, *value = NULL, *out = NULL, *dest = NULL, *name;
	const char *key;
	size_t out_len;
	int err;

	memset(&e, 0, sizeof e);
	trash = trash_path(ctx);
	if (trash == NULL) {
		move_note(ctx, NOTE_ERROR, "error.trash.home", NULL, NULL, 0);
		return;
	}
	key = d->state == STATE_ORPHAN ? d->project : NULL;
	if (key != NULL)
		take_entry(ctx, ctx->config_file, key, &value, &out, &out_len);
	free(out);
	out = NULL;
	if (value != NULL)
		move_note(ctx, NOTE_INFO, "remove.config", ctx->config_file, key,
		    0);
	if (!ctx->apply)
		goto done;
	e.removed = time(NULL);
	e.path = new_entry(ctx, trash, d->name, e.removed);
	if (e.path == NULL)
		goto done;
	e.dir = d->name;
	e.origin = d->path;
	e.project = d->project;
	e.config_dir = ctx->config_dir;
	e.config_file = ctx->config_file;
	e.projects_key = value != NULL ? (char *)key : NULL;
	e.projects_value = value;
	if (meta_write(&e) != 0) {
		move_note(ctx, NOTE_ERROR, "error.trash", e.path, NULL, errno);
		drop_entry(e.path);
		goto done;
	}
	dest = xjoin(e.path, d->name);
	if (move_tree(d->path, dest) != 0) {
		move_note(ctx, NOTE_ERROR, "error.move", d->path, NULL, errno);
		drop_entry(e.path);
		goto done;
	}
	if (stat(dest, &st) != 0 || !S_ISDIR(st.st_mode) ||
	    lstat(d->path, &st) == 0 || errno != ENOENT) {
		move_note(ctx, NOTE_ERROR, "error.remove.unconfirmed", d->path,
		    e.path, 0);
		goto done;
	}
	if (value != NULL) {
		free(value);
		value = NULL;
		err = 0;
		/* The file was read for the plan; a failure now is noted twice. */
		if (take_entry(ctx, ctx->config_file, key, &value, &out,
		    &out_len) != 0)
			err = EINVAL;
		else if (out != NULL && config_write(ctx->config_file, out,
		    out_len, &ctx->backup_done) != 0)
			err = errno;
		if (err != 0) {
			if (move_tree(dest, d->path) == 0) {
				drop_entry(e.path);
				move_note(ctx, NOTE_ERROR, "error.remove.config",
				    ctx->config_file, NULL, err);
			} else {
				move_note(ctx, NOTE_ERROR,
				    "error.remove.rollback", ctx->config_file,
				    e.path, 0);
			}
			goto done;
		}
	}
	name = path_base(e.path);
	move_note(ctx, NOTE_INFO, "remove.trash", name, NULL, 0);
	free(name);
done:
	free(e.path);
	free(dest);
	free(value);
	free(out);
	free(trash);
}

/*
 * Puts an entry back (4.6): the session directory where it was, merged
 * as in 4.3 when one of that name exists (a file on both sides stays in
 * the trash), and its projects entry into the .claude.json it came from,
 * unless the key is there already. The entry goes once nothing is left in
 * it; a projects entry that went back leaves the metadata.
 */
void trash_restore(struct move_ctx *ctx, const char *name)
{
	struct trash_entry e;
	struct stat st;
	char *trash, *src = NULL, *parent = NULL, *data, *out = NULL;
	size_t len, out_len;
	int status, have_dir, key_back = 0;

	trash = trash_path(ctx);
	if (trash == NULL) {
		move_note(ctx, NOTE_ERROR, "error.trash.home", NULL, NULL, 0);
		return;
	}
	if (trash_read(trash, name, &e) != 0) {
		move_note(ctx, NOTE_ERROR, "error.trash.none", name, NULL, 0);
		free(trash);
		return;
	}
	free(trash);
	if (e.dir == NULL) {
		move_note(ctx, NOTE_ERROR, "error.trash.meta", e.path, NULL, 0);
		goto done;
	}
	src = xjoin(e.path, e.dir);
	have_dir = lstat(src, &st) == 0 && S_ISDIR(st.st_mode);
	if (have_dir) {
		if (lstat(e.origin, &st) == 0 && !S_ISDIR(st.st_mode)) {
			move_note(ctx, NOTE_ERROR, "error.session.target",
			    e.origin, NULL, 0);
			goto done;
		}
		move_note(ctx, NOTE_INFO, lstat(e.origin, &st) == 0 ?
		    "restore.merge" : "restore.dir", e.name, e.origin, 0);
		parent = path_dir(e.origin);
		if (ctx->apply && dir_make(parent, 0700) != 0) {
			move_note(ctx, NOTE_ERROR, "error.trash", parent, NULL,
			    errno);
			goto done;
		}
		move_merge(ctx, src, e.origin, "warn.kept.trash");
	} else {
		move_note(ctx, NOTE_INFO, "restore.entry", e.name, NULL, 0);
	}
	if (e.projects_key != NULL && e.config_file != NULL) {
		if (file_read(e.config_file, &data, &len) != 0) {
			if (errno != ENOENT) {
				move_note(ctx, NOTE_ERROR, "error.read",
				    e.config_file, NULL, errno);
				goto done;
			}
			data = xstrdup("{}");
			len = 2;
		}
		status = config_put_project(data, len, e.projects_key,
		    e.projects_value, &out, &out_len);
		free(data);
		if (status == REWRITE_INVALID) {
			move_note(ctx, NOTE_WARNING, "warn.invalid",
			    e.config_file, NULL, 0);
		} else if (status == REWRITE_EXISTS) {
			move_note(ctx, NOTE_WARNING, "warn.key.trash",
			    e.projects_key, e.name, 0);
		} else {
			move_note(ctx, NOTE_INFO, "restore.config",
			    e.config_file, e.projects_key, 0);
			if (ctx->apply && config_write(e.config_file, out,
			    out_len, &ctx->backup_done) != 0)
				move_note(ctx, NOTE_ERROR, "error.file",
				    e.config_file, NULL, errno);
			else
				key_back = 1;
		}
	}
	if (!ctx->apply)
		goto done;
	if (key_back) {
		free(e.projects_key);
		free(e.projects_value);
		e.projects_key = e.projects_value = NULL;
	}
	if (lstat(src, &st) != 0 && errno == ENOENT && e.projects_key == NULL)
		drop_entry(e.path);
	else if (key_back && meta_write(&e) != 0)
		move_note(ctx, NOTE_ERROR, "error.file", e.path, NULL, errno);
done:
	free(src);
	free(parent);
	free(out);
	trash_entry_free(&e);
}

/* Deletes an entry for good, never following a symlink inside it. */
void trash_delete(struct move_ctx *ctx, const struct trash_entry *e)
{
	if (ctx->apply && tree_remove(e->path) != 0)
		move_note(ctx, NOTE_ERROR, "error.trash.delete", e->path, NULL,
		    errno);
}
